#!/usr/bin/env node
/**
 * Tests for workflows/dev-loop.js: probes survive from the review report to the fixer and the verifier.
 * Zero dependencies — `node:test` on Node 18+; the shared harness is tools/dev-loop.harness.mjs.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, ARGS_M, review, finding, impl, gate, mergeReviews, ROOT } from './dev-loop.harness.mjs';

const V_ARGS = { ...ARGS_M, verify: 'node --test x' };
const T2 = (tree, churn = 3) => ({ tree, files: ['src/Orders/OrdersQuery.cs'], churn });
const treeless = (extra = {}) => impl({ gate: gate('green', { tree: '' }), ...extra });
const probe = (name) => ({ path: `deliver/probes/${name}.mjs`, cmd: `node -e "probe ${name}"` });

test('given a REVIEW report whose probes field lists a probe not attached to any finding, when the fix round runs and the verifier is briefed, then the verifier brief lists that probe to rerun', async () => {
  // Given
  const loose = probe('loose');
  const report = { ...review([], [finding()]), probes: [loose] };
  const impls = [treeless(), impl({ gate: gate('green', { tree: '' }), snapshot: T2('t2', 10) }), treeless({ snapshot: T2('t3', 10) })];

  // When
  const { calls } = await run(V_ARGS, [report], impls);

  // Then
  const verifier = calls.find(c => c.opts.label === 'reviewer V · round 2 · verify the fixes');
  assert.ok(verifier, 'the verifier ran');
  assert.ok(verifier.prompt.includes(loose.cmd));
  assert.ok(verifier.prompt.includes(loose.path));
});

test('given readers A and B report the same finding each with a different probe path, when mergeReviews merges them, then the kept finding carries both probes, de-duplicated by path', () => {
  // Given
  const [p1, p2] = [probe('one'), probe('two')];
  const fromA = finding({ probes: [p1] });
  const fromB = finding({ probes: [p1, p2] });

  // When
  const merged = mergeReviews([{ found: [fromA] }, { found: [fromB] }], ROOT);

  // Then
  assert.equal(merged.found.length, 1);
  assert.deepEqual(merged.found[0].probes.map(q => q.path).sort(), [p1.path, p2.path].sort());
});

test('given the fixer brief for a finding with probes, when it is built, then it asks a new test file per probe', async () => {
  // Given
  const withProbe = finding({ probes: [probe('one')] });

  // When
  const { calls } = await run(V_ARGS, [review([], [withProbe])], [treeless(), treeless({ snapshot: T2('t2', 10) }), treeless({ snapshot: T2('t3', 10) })]);

  // Then
  const fixer = calls.find(c => c.opts.label === 'fix round 1 findings');
  assert.ok(fixer, 'the fix round ran');
  assert.match(fixer.prompt, /one new test file per probe/);
});

test('given args with verify set and no unit, when the fixer brief for a finding with probes is built, then it asks one new test file per probe and carries no gate --red --probe command', async () => {
  // Given
  const withProbe = finding({ probes: [probe('one')] });

  // When
  const { calls } = await run(V_ARGS, [review([], [withProbe])], [treeless(), treeless({ snapshot: T2('t2', 10) }), treeless({ snapshot: T2('t3', 10) })]);

  // Then
  const fixer = calls.find(c => c.opts.label === 'fix round 1 findings');
  assert.ok(fixer, 'the fix round ran');
  assert.match(fixer.prompt, /one new test file per probe/);
  assert.doesNotMatch(fixer.prompt, /--red --probe/);
});

test('given args with unit set, when the fixer brief for a finding with probes is built, then the --red --probe command uses that unit', async () => {
  // Given
  const withProbe = finding({ probes: [probe('one')] });
  const args = { ...V_ARGS, unit: 'node --test unit-x' };

  // When
  const { calls } = await run(args, [review([], [withProbe])], [treeless(), treeless({ snapshot: T2('t2', 10) }), treeless({ snapshot: T2('t3', 10) })]);

  // Then
  const fixer = calls.find(c => c.opts.label === 'fix round 1 findings');
  assert.ok(fixer, 'the fix round ran');
  assert.match(fixer.prompt, /--red --probe --unit 'node --test unit-x'/);
});
